actions.action:
tk_status: f.tk_status, tk_reporter: f.tk_reporter, tk_reporter_name: f.tk_reporter_name,
tk_org_id: f.tk_org_id, tk_org_name: f.tk_org_name, tk_subject: f.tk_subject;

change tk_status value { "draft" }
// Vlastnik je AUTOR pripadu, nie loggedUser() - pripad moze zalozit aj niekto
// v mene zakaznika (B28).
def author = ((useCase.author?.id ?: "") as String)
if (!author) {
    author = ((loggedUser()?.stringId ?: "") as String)
}
if (author) {
    change tk_reporter value { [author] }
    change tk_reporter_name value { person_name(author) }
    def org = org_of(author)
    if (org != null) {
        change tk_org_id value { org.stringId }
        change tk_org_name value { ((org.dataSet["org_name"]?.value ?: org.title) as String) }
    }
}
changeCaseProperty("title").about { title_of(tk_subject) }
changeCaseProperty("color").about { "grey" }

document.function:
{ def name ->
    // Sesterska siet - identifikator nesie URI cestu (it/service_desk/...).
    def pid = useCase.processIdentifier as String
    def prefix = pid.contains("/") ? pid.substring(0, pid.lastIndexOf("/") + 1) : ""
    return prefix + (name as String)
}

{ def userId ->
    // Organizacia, v ktorej clovek je. `findCases { it.dataSet... }`
    // nefunguje, filtruje sa v Groovy.
    def id = (userId ?: "") as String
    if (!id) return null
    return findCases { it.processIdentifier.eq(sister("sd_organization")) }.find { c ->
        userIdsOf(c.dataSet["org_members"]?.value).contains(id)
    }
}

{ def org ->
    // `findCase { it.stringId.eq(id) }` vracia vzdy null - hlada sa v Groovy.
    def id = ((org?.dataSet?.get("org_plan")?.value ?: "") as String)
    if (!id) return null
    return findCases { it.processIdentifier.eq(sister("sd_sla_plan")) }.find { it.stringId == id }
}

{ def userId ->
    def names = menaUzivatelov([userId as String])
    def m = names ? (names[0] as String) : ""
    return (m && m != "unknown unknown") ? m : (emailyOf([userId as String])[0] ?: (userId as String))
}

{ ->
    def u = loggedUser()
    return u == null ? "?" : person_name(u.stringId)
}

{ def tk_subject ->
    // Cislo a predmet, BEZ stavu - Case.title sa neprekladá (RUNBOOK 9).
    def no = ((useCase.visualId ?: "") as String)
    def s = ((tk_subject?.value ?: "") as String).trim()
    return s ? (no + " · " + s) : no
}

{ def field, def author, def text ->
    // Konverzacia sa len pripisuje, nikdy neprepisuje - je to historia tiketu.
    def when = java.time.LocalDateTime.now().format(
            java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm"))
    def old = ((field.value ?: "") as String)
    def line = when + " · " + (author as String) + ":\n" + (text as String)
    return old ? (old + "\n\n" + line) : line
}

{ def field, def message ->
    // Validacia v `pre`, ktoru `required` neoveri (pole moze byt skryte).
    // Odmietnutie vrati HTTP 200 a dovod v tele ako `error`.
    if (!((field.value ?: "") as String).trim()) {
        throw new java.lang.IllegalStateException(message as String)
    }
}

{ def field ->
    // Popis zvolenej moznosti enumeration_map v aktualnom jazyku.
    def k = field.value as String
    if (!k) return ""
    def o = field.options?.get(k)
    return o == null ? k : (o.defaultValue as String)
}

{ def start, def minutes, def from, def to ->
    // Pracovny cas Po-Pi from:00-to:00. Sviatky tato verzia neriesi.
    if (start == null) return null
    int f = (from == null ? 8 : (from as Number).intValue())
    int e = (to == null ? 16 : (to as Number).intValue())
    def cur = start
    long remaining = ((minutes ?: 0) as Number).longValue()
    int guard = 0
    while (remaining > 0 && guard < 5000) {
        guard++
        if (cur.dayOfWeek.value >= 6 || cur.hour >= e) {
            cur = cur.toLocalDate().plusDays(1).atTime(f, 0)
            continue
        }
        if (cur.hour < f) {
            cur = cur.toLocalDate().atTime(f, 0)
            continue
        }
        def endOfDay = e >= 24 ? cur.toLocalDate().plusDays(1).atStartOfDay() : cur.toLocalDate().atTime(e, 0)
        long avail = java.time.temporal.ChronoUnit.MINUTES.between(cur, endOfDay)
        if (avail >= remaining) return cur.plusMinutes(remaining)
        remaining -= avail
        cur = cur.toLocalDate().plusDays(1).atTime(f, 0)
    }
    return cur
}

{ def a, def b, def from, def to ->
    // Pracovne minuty medzi dvoma okamihmi - na pauzu SLA.
    if (a == null || b == null || !b.isAfter(a)) return 0L
    int f = (from == null ? 8 : (from as Number).intValue())
    int e = (to == null ? 16 : (to as Number).intValue())
    long total = 0
    def day = a.toLocalDate()
    int guard = 0
    while (!day.isAfter(b.toLocalDate()) && guard < 3700) {
        guard++
        if (day.dayOfWeek.value < 6) {
            def s = day.atTime(f, 0)
            def en = e >= 24 ? day.plusDays(1).atStartOfDay() : day.atTime(e, 0)
            def lo = a.isAfter(s) ? a : s
            def hi = b.isBefore(en) ? b : en
            if (hi.isAfter(lo)) total += java.time.temporal.ChronoUnit.MINUTES.between(lo, hi)
        }
        day = day.plusDays(1)
    }
    return total
}

{ def priority ->
    return (["critical": "red", "high": "orange", "medium": "blue", "low": "green"][priority as String] ?: "blue") as String
}

{ def to, def subject, def body ->
    // Notifikacia nesmie zhodit prechod - `notifikuj` nikdy nehadze a bez
    // SMTP vrati 0.
    notifikuj(to, ((useCase.visualId ?: "") as String) + " - " + (subject as String),
            (body as String) + "\n\n" + ((useCase.title ?: "") as String))
}

{ def tk_agents ->
    // Komu ide oznam na strane Service Desku: agenti organizacie, a ked
    // ziadni nie su, spravcovia - tiket nesmie ostat bez adresata.
    def a = userIdsOf(tk_agents.value)
    return a ?: usersWithRoleAll("sd_admin", useCase.processIdentifier as String)
}

{ def sla_first_response_at, def sla_response_met, def sla_response_due ->
    // Prva reakcia sa zapisuje len raz.
    if (sla_first_response_at.value != null) return
    def now = java.time.LocalDateTime.now()
    def due = sla_response_due.value
    change sla_first_response_at value { now }
    change sla_response_met value { due == null || !now.isAfter(due) }
}

{ def sla_paused_since ->
    if (sla_paused_since.value == null) {
        change sla_paused_since value { java.time.LocalDateTime.now() }
    }
}

{ def sla_paused_since, def sla_paused_minutes, def sla_resolution_due, def tk_submitted_at,
  def sla_res_hours, def sla_work_from, def sla_work_to ->
    // Pauza skoncila: jej pracovne minuty sa pripocitaju a termin vyriesenia
    // sa prepocita od podania.
    def since = sla_paused_since.value
    if (since == null) return
    def now = java.time.LocalDateTime.now()
    long paused = ((sla_paused_minutes.value ?: 0) as Number).longValue() +
            business_minutes(since, now, sla_work_from.value, sla_work_to.value)
    change sla_paused_minutes value { paused }
    change sla_paused_since value { null }
    long total = ((sla_res_hours.value ?: 0) as Number).longValue() * 60 + paused
    change sla_resolution_due value {
        business_deadline(tk_submitted_at.value, total, sla_work_from.value, sla_work_to.value)
    }
}

{ def x ->
    // Telo hodin SLA - vola ho t_tick aj t_tock (dve polovice jedneho
    // cyklu, pozri t_tick). `x` su polia z hlavicky akcie.
    def tk_status = x.tk_status
    def tk_sla_state = x.tk_sla_state
    def tk_keep_ticking = x.tk_keep_ticking
    def tk_close_due = x.tk_close_due
    def tk_agents = x.tk_agents
    def tk_responder_id = x.tk_responder_id
    def tk_org_name = x.tk_org_name
    def tk_submitted_at = x.tk_submitted_at
    def sla_response_due = x.sla_response_due
    def sla_resolution_due = x.sla_resolution_due
    def sla_first_response_at = x.sla_first_response_at
    def sla_resolved_at = x.sla_resolved_at
    def sla_paused_since = x.sla_paused_since
    def sla_paused_minutes = x.sla_paused_minutes
    def sla_resp_hours = x.sla_resp_hours
    def sla_res_hours = x.sla_res_hours
    def sla_work_from = x.sla_work_from
    def sla_work_to = x.sla_work_to
    def sla_autoclose_days = x.sla_autoclose_days
    def sla_response_warned = x.sla_response_warned
    def sla_resolution_warned = x.sla_resolution_warned
    def sla_response_breached = x.sla_response_breached
    def sla_resolution_breached = x.sla_resolution_breached
    def st = tk_status.value as String
    change tk_close_due value { 0 }
    if (st in ["closed", "rejected", "draft"]) {
        // Hodiny sa zastavia: token sa do p_clock nevrati.
        change tk_keep_ticking value { 0 }
        return
    }
    change tk_keep_ticking value { 1 }
    def now = java.time.LocalDateTime.now()
    def from = sla_work_from.value
    def to = sla_work_to.value
    def when = { d -> d == null ? "-" : d.format(java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm")) }
    def agents = staff(tk_agents)
    def escalate = (agents + usersWithRoleAll("sd_admin", useCase.processIdentifier as String)).unique()
    def org = ((tk_org_name.value ?: "") as String)

    // Prva reakcia - kym neprisla.
    if (sla_first_response_at.value == null && sla_response_due.value != null) {
        def due = sla_response_due.value
        long total = ((sla_resp_hours.value ?: 0) as Number).longValue() * 60
        long used = business_minutes(tk_submitted_at.value, now, from, to)
        if (!now.isBefore(due)) {
            if (sla_response_breached.value != true) {
                change sla_response_breached value { true }
                notify(escalate, "SLA BREACHED - first response overdue (" + org + ")",
                        "The first response was due at " + when(due) + ". Nobody has answered the customer yet.")
            }
        } else if (used * 4 >= total * 3 && sla_response_warned.value != true) {
            change sla_response_warned value { true }
            notify(agents, "SLA - first response due at " + when(due) + " (" + org + ")",
                    "75 % of the response time is gone. Answer, accept or reject the ticket.")
        }
    }

    // Vyriesenie - len kym bezi (nie v pauze a nie vyriesene).
    if (sla_resolved_at.value == null && sla_paused_since.value == null && sla_resolution_due.value != null) {
        def due = sla_resolution_due.value
        long total = ((sla_res_hours.value ?: 0) as Number).longValue() * 60
        long used = business_minutes(tk_submitted_at.value, now, from, to) -
                ((sla_paused_minutes.value ?: 0) as Number).longValue()
        def h = ((tk_responder_id.value ?: "") as String)
        if (!now.isBefore(due)) {
            if (sla_resolution_breached.value != true) {
                change sla_resolution_breached value { true }
                notify(escalate, "SLA BREACHED - resolution overdue (" + org + ")",
                        "The ticket should have been resolved by " + when(due) + ".")
            }
        } else if (used * 4 >= total * 3 && sla_resolution_warned.value != true) {
            change sla_resolution_warned value { true }
            notify(h ? [h] : agents, "SLA - resolution due at " + when(due) + " (" + org + ")",
                    "75 % of the resolution time is gone.")
        }
    }

    // Stav pre zoznamy a zobrazenie "SLA at risk". Vyrieseny tiket si drzi
    // stav z vyriesenia (met / breached).
    if (st != "resolved") {
        def state = "ok"
        if (sla_response_breached.value == true || sla_resolution_breached.value == true) {
            state = "breached"
        } else if ((sla_response_warned.value == true && sla_first_response_at.value == null) ||
                (sla_resolution_warned.value == true && sla_resolved_at.value == null)) {
            state = "at_risk"
        }
        change tk_sla_state value { state }
    }

    // Vyrieseny tiket, na ktory zakaznik neodpoveda, sa zatvori sam.
    if (st == "resolved" && sla_resolved_at.value != null) {
        int days = (sla_autoclose_days.value == null ? 5 : (sla_autoclose_days.value as Number).intValue())
        int f = (from == null ? 8 : (from as Number).intValue())
        int e = (to == null ? 16 : (to as Number).intValue())
        long worked = business_minutes(sla_resolved_at.value, now, from, to)
        if (worked >= (long) days * (e - f) * 60) {
            change tk_close_due value { 1 }
        }
    }
}

actions.action:
tk_type: f.tk_type, t_submit: t.t_submit,
tk_cat_bug: f.tk_cat_bug, tk_environment: f.tk_environment, tk_steps: f.tk_steps, tk_expected: f.tk_expected,
tk_cat_change: f.tk_cat_change, tk_justification: f.tk_justification, tk_wanted_date: f.tk_wanted_date,
tk_cat_service: f.tk_cat_service, tk_system: f.tk_system, tk_window: f.tk_window;

// Formular ukaze len polia zvoleneho typu. Povinnost sa overuje v `pre`
// podania, nie cez `required` - skryte povinne pole by podanie zablokovalo.
def t = tk_type.value as String
make tk_cat_bug, editable on t_submit when { return t == "bug" }
make tk_cat_bug, hidden on t_submit when { return t != "bug" }
make tk_environment, editable on t_submit when { return t == "bug" }
make tk_environment, hidden on t_submit when { return t != "bug" }
make tk_steps, editable on t_submit when { return t == "bug" }
make tk_steps, hidden on t_submit when { return t != "bug" }
make tk_expected, editable on t_submit when { return t == "bug" }
make tk_expected, hidden on t_submit when { return t != "bug" }
make tk_cat_change, editable on t_submit when { return t == "change" }
make tk_cat_change, hidden on t_submit when { return t != "change" }
make tk_justification, editable on t_submit when { return t == "change" }
make tk_justification, hidden on t_submit when { return t != "change" }
make tk_wanted_date, editable on t_submit when { return t == "change" }
make tk_wanted_date, hidden on t_submit when { return t != "change" }
make tk_cat_service, editable on t_submit when { return t == "service" }
make tk_cat_service, hidden on t_submit when { return t != "service" }
make tk_system, editable on t_submit when { return t == "service" }
make tk_system, hidden on t_submit when { return t != "service" }
make tk_window, editable on t_submit when { return t == "service" }
make tk_window, hidden on t_submit when { return t != "service" }

tk_type: f.tk_type, tk_subject: f.tk_subject, tk_priority: f.tk_priority, tk_description: f.tk_description,
tk_cat_bug: f.tk_cat_bug, tk_environment: f.tk_environment, tk_steps: f.tk_steps, tk_expected: f.tk_expected,
tk_cat_change: f.tk_cat_change, tk_justification: f.tk_justification, tk_wanted_date: f.tk_wanted_date,
tk_cat_service: f.tk_cat_service, tk_system: f.tk_system, tk_window: f.tk_window, tk_details: f.tk_details,
tk_reporter: f.tk_reporter, tk_org_id: f.tk_org_id, tk_org_name: f.tk_org_name,
tk_org_members: f.tk_org_members, tk_agents: f.tk_agents, tk_status: f.tk_status,
tk_submitted_at: f.tk_submitted_at, tk_conversation: f.tk_conversation,
sla_response_due: f.sla_response_due, sla_resolution_due: f.sla_resolution_due,
sla_resp_hours: f.sla_resp_hours, sla_res_hours: f.sla_res_hours,
sla_work_from: f.sla_work_from, sla_work_to: f.sla_work_to, sla_paused_minutes: f.sla_paused_minutes,
sla_autoclose_days: f.sla_autoclose_days, tk_sla_state: f.tk_sla_state, tk_keep_ticking: f.tk_keep_ticking;

must(tk_type, "Pick what you need help with.")
must(tk_priority, "Pick the priority.")
must(tk_subject, "Fill in the subject.")
must(tk_description, "Describe what you need.")
def type = tk_type.value as String
def lines = []
if (type == "bug") {
    must(tk_cat_bug, "Pick the kind of bug.")
    lines << ("Kind: " + opt(tk_cat_bug))
    if (tk_environment.value) lines << ("Environment: " + opt(tk_environment))
    if (((tk_steps.value ?: "") as String).trim()) lines << ("Steps to reproduce:\n" + tk_steps.value)
    if (((tk_expected.value ?: "") as String).trim()) lines << ("Expected / actual:\n" + tk_expected.value)
} else if (type == "change") {
    must(tk_cat_change, "Pick the kind of change.")
    lines << ("Kind: " + opt(tk_cat_change))
    if (((tk_justification.value ?: "") as String).trim()) lines << ("Why:\n" + tk_justification.value)
    if (tk_wanted_date.value) lines << ("Wanted by: " + tk_wanted_date.value)
} else if (type == "service") {
    must(tk_cat_service, "Pick the kind of service.")
    lines << ("Kind: " + opt(tk_cat_service))
    if (((tk_system.value ?: "") as String).trim()) lines << ("System: " + tk_system.value)
    if (((tk_window.value ?: "") as String).trim()) lines << ("Time window: " + tk_window.value)
}

def author = userIdsOf(tk_reporter.value)[0]
if (!author) author = loggedUser()?.stringId
// Organizacia sa overuje ZNOVA, nie z `tk_org_id` z konceptu: medzi
// zalozenim a podanim mohol byt clovek odobraty alebo zmluva ukoncena.
def org = org_of(author)
if (org == null) {
    throw new java.lang.IllegalStateException(
            "Your account is not assigned to any organization, so the ticket has nowhere to go. Ask your Service Desk admin to add you.")
}
if (org.dataSet["org_active"]?.value == false) {
    throw new java.lang.IllegalStateException(
            "The contract of your organization is not active - new tickets cannot be submitted.")
}
def plan = plan_of(org)
def p = tk_priority.value as String
// null = plan to pole nema (alebo organizacia plan nema) -> standard.
// 0 je platna hodnota: "okamzite" (reakcia) a "hned" (zatvorenie).
def num = { String k, int dflt ->
    def v = plan?.dataSet?.get(k)?.value
    return v == null ? dflt : Math.max(0, (v as Number).intValue())
}
int resp = num("sp_resp_" + p, ["critical": 1, "high": 2, "medium": 4, "low": 8][p] ?: 4)
int res = num("sp_res_" + p, ["critical": 8, "high": 16, "medium": 40, "low": 80][p] ?: 40)
int from = num("sp_work_from", 8)
int to = num("sp_work_to", 16)
int autoclose = num("sp_autoclose_days", 5)
def now = java.time.LocalDateTime.now()
def members = userIdsOf(org.dataSet["org_members"]?.value).findAll { it != author }
def agents = usersWithRole(org.dataSet["org_agents"]?.value, "sd_agent", useCase.processIdentifier as String)

change tk_details value { lines.join("\n\n") }
change tk_org_id value { org.stringId }
change tk_org_name value { ((org.dataSet["org_name"]?.value ?: org.title) as String) }
change tk_org_members value { members }
change tk_agents value { agents }
change tk_status value { "new" }
change tk_submitted_at value { now }
change sla_resp_hours value { resp }
change sla_res_hours value { res }
change sla_work_from value { from }
change sla_work_to value { to }
change sla_paused_minutes value { 0 }
change sla_autoclose_days value { autoclose }
change tk_sla_state value { "ok" }
change tk_keep_ticking value { 1 }
change sla_response_due value { business_deadline(now, resp * 60, from, to) }
change sla_resolution_due value { business_deadline(now, res * 60, from, to) }
change tk_conversation value { append(tk_conversation, me(), "Ticket submitted.") }
changeCaseProperty("title").about { title_of(tk_subject) }
changeCaseProperty("color").about { color_of(p) }
notify(staff(tk_agents), "new ticket from " + ((tk_org_name.value ?: "") as String),
        ((tk_description.value ?: "") as String))

tk_status: f.tk_status;

if ((tk_status.value as String) == "draft") {
    def id = useCase.stringId
    async.run {
        workflowService.deleteCase(id)
    }
}

tk_customer_msg: f.tk_customer_msg, tk_conversation: f.tk_conversation, tk_status: f.tk_status,
tk_notice: f.tk_notice, tk_agents: f.tk_agents, tk_responder_id: f.tk_responder_id,
sla_paused_since: f.sla_paused_since, sla_paused_minutes: f.sla_paused_minutes,
sla_resolution_due: f.sla_resolution_due, tk_submitted_at: f.tk_submitted_at,
sla_res_hours: f.sla_res_hours, sla_work_from: f.sla_work_from, sla_work_to: f.sla_work_to;

// Odmietnutie sa NEHADZE: z tlacidla by skoncilo ako chyba requestu.
def text = ((tk_customer_msg.value ?: "") as String).trim()
if (!text) {
    change tk_notice value { "Write your message first." }
    return
}
def st = tk_status.value as String
if (st in ["closed", "rejected"]) {
    change tk_notice value { "This ticket is closed. Please create a new ticket." }
    return
}
change tk_conversation value { append(tk_conversation, me(), text) }
change tk_customer_msg value { "" }
if (st == "waiting") {
    resume(sla_paused_since, sla_paused_minutes, sla_resolution_due, tk_submitted_at,
            sla_res_hours, sla_work_from, sla_work_to)
    change tk_status value { "in_progress" }
}
change tk_notice value { "Message sent." }
def h = ((tk_responder_id.value ?: "") as String)
notify(h ? [h] : staff(tk_agents), "the customer replied", text)

tk_reopen_reason: f.tk_reopen_reason, tk_conversation: f.tk_conversation, tk_status: f.tk_status,
tk_responder_id: f.tk_responder_id, tk_priority: f.tk_priority, tk_agents: f.tk_agents,
sla_resolved_at: f.sla_resolved_at, sla_resolution_met: f.sla_resolution_met,
sla_paused_since: f.sla_paused_since, sla_paused_minutes: f.sla_paused_minutes,
sla_resolution_due: f.sla_resolution_due, tk_submitted_at: f.tk_submitted_at,
sla_res_hours: f.sla_res_hours, sla_work_from: f.sla_work_from, sla_work_to: f.sla_work_to,
tk_sla_state: f.tk_sla_state;

must(tk_reopen_reason, "Write why the ticket is not resolved.")
def text = ((tk_reopen_reason.value ?: "") as String).trim()
// Cas vo "vyriesenom" sa do lehoty nepocita - je to pauza.
resume(sla_paused_since, sla_paused_minutes, sla_resolution_due, tk_submitted_at,
        sla_res_hours, sla_work_from, sla_work_to)
change sla_resolved_at value { null }
change sla_resolution_met value { null }
if ((tk_sla_state.value as String) == "met") {
    change tk_sla_state value { "ok" }
}
change tk_conversation value { append(tk_conversation, me(), "Reopened: " + text) }
change tk_reopen_reason value { "" }
change tk_status value { "in_progress" }
changeCaseProperty("color").about { color_of(tk_priority.value) }
def h = ((tk_responder_id.value ?: "") as String)
notify(h ? [h] : staff(tk_agents), "the customer reopened the ticket", text)

tk_conversation: f.tk_conversation, tk_status: f.tk_status;

change tk_conversation value { append(tk_conversation, me(), "Confirmed the ticket as resolved.") }
change tk_status value { "closed" }
changeCaseProperty("color").about { "grey" }

tk_agent_msg: f.tk_agent_msg, tk_conversation: f.tk_conversation, tk_status: f.tk_status,
tk_notice: f.tk_notice, tk_reporter: f.tk_reporter, sla_first_response_at: f.sla_first_response_at,
sla_response_met: f.sla_response_met, sla_response_due: f.sla_response_due;

def text = ((tk_agent_msg.value ?: "") as String).trim()
if (!text) {
    change tk_notice value { "Write the message first." }
    return
}
if ((tk_status.value as String) in ["draft", "closed", "rejected"]) {
    change tk_notice value { "The ticket is not open - the message was not sent." }
    return
}
change tk_conversation value { append(tk_conversation, me() + " (Service Desk)", text) }
change tk_agent_msg value { "" }
first_response(sla_first_response_at, sla_response_met, sla_response_due)
change tk_notice value { "Message sent to the customer." }
notify(tk_reporter.value, "reply from the Service Desk", text)

tk_agent_msg: f.tk_agent_msg, tk_conversation: f.tk_conversation, tk_status: f.tk_status,
tk_notice: f.tk_notice, tk_reporter: f.tk_reporter, sla_first_response_at: f.sla_first_response_at,
sla_response_met: f.sla_response_met, sla_response_due: f.sla_response_due,
sla_paused_since: f.sla_paused_since;

def text = ((tk_agent_msg.value ?: "") as String).trim()
if (!text) {
    change tk_notice value { "Write what you need from the customer first." }
    return
}
if ((tk_status.value as String) != "in_progress") {
    change tk_notice value { "Accept the ticket first - only a ticket in progress can wait for the customer." }
    return
}
change tk_conversation value { append(tk_conversation, me() + " (Service Desk)", text) }
change tk_agent_msg value { "" }
first_response(sla_first_response_at, sla_response_met, sla_response_due)
// Kym zakaznik neodpovie, lehota vyriesenia stoji.
pause(sla_paused_since)
change tk_status value { "waiting" }
change tk_notice value { "Sent. The ticket waits for the customer." }
notify(tk_reporter.value, "we need something from you", text)

tk_note_new: f.tk_note_new, tk_internal: f.tk_internal, tk_notice: f.tk_notice;

def text = ((tk_note_new.value ?: "") as String).trim()
if (!text) {
    change tk_notice value { "Write the note first." }
    return
}
change tk_internal value { append(tk_internal, me(), text) }
change tk_note_new value { "" }
change tk_notice value { "Note added." }

tk_status: f.tk_status, tk_responder: f.tk_responder, tk_responder_id: f.tk_responder_id,
tk_conversation: f.tk_conversation, tk_reporter: f.tk_reporter,
sla_first_response_at: f.sla_first_response_at, sla_response_met: f.sla_response_met,
sla_response_due: f.sla_response_due;

change tk_status value { "in_progress" }
change tk_responder value { me() }
change tk_responder_id value { (loggedUser()?.stringId ?: "") as String }
first_response(sla_first_response_at, sla_response_met, sla_response_due)
change tk_conversation value { append(tk_conversation, me() + " (Service Desk)", "Accepted the ticket.") }
notify(tk_reporter.value, "your ticket is being handled", "Handled by: " + me())

tk_reject_reason: f.tk_reject_reason, tk_status: f.tk_status, tk_conversation: f.tk_conversation,
tk_reporter: f.tk_reporter, tk_responder: f.tk_responder, tk_responder_id: f.tk_responder_id,
sla_first_response_at: f.sla_first_response_at, sla_response_met: f.sla_response_met,
sla_response_due: f.sla_response_due;

must(tk_reject_reason, "Write why the ticket is rejected - the customer reads it.")
def text = ((tk_reject_reason.value ?: "") as String).trim()
change tk_status value { "rejected" }
change tk_responder value { me() }
change tk_responder_id value { (loggedUser()?.stringId ?: "") as String }
first_response(sla_first_response_at, sla_response_met, sla_response_due)
change tk_conversation value { append(tk_conversation, me() + " (Service Desk)", "Rejected: " + text) }
changeCaseProperty("color").about { "grey" }
notify(tk_reporter.value, "your ticket was rejected", text)

tk_resolution: f.tk_resolution, tk_status: f.tk_status, tk_conversation: f.tk_conversation,
tk_reporter: f.tk_reporter, tk_responder: f.tk_responder, tk_responder_id: f.tk_responder_id,
sla_resolved_at: f.sla_resolved_at, sla_resolution_met: f.sla_resolution_met,
sla_resolution_due: f.sla_resolution_due, sla_paused_since: f.sla_paused_since,
sla_paused_minutes: f.sla_paused_minutes, tk_submitted_at: f.tk_submitted_at,
sla_res_hours: f.sla_res_hours, sla_work_from: f.sla_work_from, sla_work_to: f.sla_work_to,
tk_sla_state: f.tk_sla_state;

must(tk_resolution, "Write the resolution - the customer reads it.")
// Vyriesenie pocas cakania na zakaznika: pauza konci teraz.
resume(sla_paused_since, sla_paused_minutes, sla_resolution_due, tk_submitted_at,
        sla_res_hours, sla_work_from, sla_work_to)
def now = java.time.LocalDateTime.now()
def due = sla_resolution_due.value
change sla_resolved_at value { now }
change sla_resolution_met value { due == null || !now.isAfter(due) }
if ((tk_sla_state.value as String) != "breached") {
    change tk_sla_state value { (due == null || !now.isAfter(due)) ? "met" : "breached" }
}
// Kym zakaznik vyriesenie nepotvrdi alebo neotvori znova, lehota stoji.
pause(sla_paused_since)
if (!((tk_responder_id.value ?: "") as String)) {
    change tk_responder value { me() }
    change tk_responder_id value { (loggedUser()?.stringId ?: "") as String }
}
change tk_status value { "resolved" }
change tk_conversation value { append(tk_conversation, me() + " (Service Desk)", "Resolved: " + tk_resolution.value) }
changeCaseProperty("color").about { "green" }
notify(tk_reporter.value, "your ticket is resolved",
        ((tk_resolution.value ?: "") as String) + "\n\nIf it is not, reopen the ticket in the Service Desk.")

tk_conversation: f.tk_conversation, tk_status: f.tk_status, tk_reporter: f.tk_reporter,
sla_autoclose_days: f.sla_autoclose_days;

def days = (sla_autoclose_days.value == null ? 5 : (sla_autoclose_days.value as Number).intValue())
change tk_conversation value {
    append(tk_conversation, "Service Desk", "Closed automatically - no reply within " + days + " working days after the resolution.")
}
change tk_status value { "closed" }
changeCaseProperty("color").about { "grey" }
notify(tk_reporter.value, "your ticket was closed",
        "We did not hear back after the resolution, so the ticket is closed. If the problem returns, create a new ticket.")
